arguments.command:
python3 -c "import zipfile,re
from xml.etree import ElementTree as ET
HP_NS='http://www.hancom.co.kr/hwpml/2010/HWPML'
ns={'hp':HP_NS}

def local(tag):
    return tag.split('}',1)[1] if tag.startswith('{') else tag

with zipfile.ZipFile('/root/training_feedback_template.hwpx','r') as zt, zipfile.ZipFile('/root/training_feedback_ready.hwpx','r') as zo:
    for sec in ['Contents/section0.xml','Contents/section1.xml']:
        t_root=ET.fromstring(zt.read(sec))
        o_root=ET.fromstring(zo.read(sec))
        # map paragraphs by id
        t_ps={p.get('id'):p for p in t_root.findall('.//hp:p',ns)}
        o_ps={p.get('id'):p for p in o_root.findall('.//hp:p',ns)}
        bad=[]
        for pid,t_p in t_ps.items():
            o_p=o_ps.get(pid)
            if o_p is None: continue
            t_text=''.join((x.text or '') for x in t_p.findall('.//hp:t',ns))
            o_text=''.join((x.text or '') for x in o_p.findall('.//hp:t',ns))
            changed = t_text!=o_text
            if changed:
                # look for any element with 'lineseg' in localname
                has=False
                for el in o_p.iter():
                    if 'lineseg' in local(el.tag).lower():
                        has=True; break
                if has:
                    bad.append((pid,o_text))
        print(sec,'modified paras with remaining lineseg:',bad)
"

